function Engine(storage,now){this.storage=storage;this.now=now||Date.now;this.d=initial(this.now());try{var d=JSON.parse(storage.getItem('novaRTS1'));if(d&&d.version===1&&Array.isArray(d.buildings)&&d.buildings.some(function(b){return b.type==='hq';})&&d.buildings.every(function(b){return !!B[b.type]&&Number.isFinite(b.x)&&Number.isFinite(b.y)&&b.lv>=1&&b.lv<=5;})&&Array.isArray(d.army)&&d.army.length>=4&&d.army.length<=U.length&&d.army.every(function(n){return Number.isFinite(n)&&n>=0;})&&Array.isArray(d.queue)&&Number.isFinite(d.gold)&&Number.isFinite(d.power)){this.d=d;}}catch(e){}while(this.d.army.length<U.length)this.d.army.push(0);if(!Number.isFinite(this.d.gems))this.d.gems=30;if(!this.d.checkin)this.d.checkin={day:-1,streak:0};if(!Array.isArray(this.d.rewardIds))this.d.rewardIds=[];this.raid=null;this.defense=null;if(!this.d.tasks)this.d.tasks={day:-1,build:0,train:0,win:0,defend:0,claimed:[]};if(!this.d.defenseLevel)this.d.defenseLevel=1;this.sync();}
