// Production is integrated across completion boundaries; full stores discard production, never bank it.
Engine.prototype.resourceCapacity=function(){return 2000+1000*(this.hq()-1)+this.d.buildings.filter(function(b){return b.type==='storage'&&active(b);}).reduce(function(n,b){return n+2000*b.lv;},0);};
