Engine.prototype.upgradeWalls=function(id,mode,quote){this.sync();var q=this.wallQuote(id,mode);if(!q.ids.length)return'ไม่มีกำแพงที่อัปเกรดได้';if(JSON.stringify(q)!==quote)return'รายการเปลี่ยน กรุณาเลือกใหม่';if(this.d.buildings.some(function(b){return b.until;}))return'ช่างกำลังทำงาน';if(this.d.gold<q.gold||this.d.power<q.power)return'ทรัพยากรไม่พอ';this.d.gold-=q.gold;this.d.power-=q.power;var self=this;this.d.buildings.forEach(function(b){if(q.ids.indexOf(b.id)>=0){b.lv++;self.progress('build');}});this.save();return'';};
Engine.prototype.speedTraining=function(quoted){this.sync();if(!this.d.queue.length)return'คิวฝึกเสร็จแล้ว';var cost=Math.ceil((Math.max.apply(null,this.d.queue.map(function(q){return q.until;}))-this.now())/30000);if(cost>quoted)return'ราคาเปลี่ยน กรุณายืนยันใหม่';if(this.d.gems<cost)return'เพชรไม่พอ';this.d.gems-=cost;var self=this;this.d.queue.forEach(function(q){q.until=self.now();});this.sync();return'';};
Engine.prototype.empty=function(x,y,ignore){return x>=1&&y>=1&&x<=10&&y<=10&&!this.d.buildings.some(function(b){return b.id!==ignore&&b.x===x&&b.y===y;});};
Engine.prototype.build=function(type,x,y){this.sync();var b=B[type];if(!b||type==='hq'||!this.empty(x,y))return'วางตรงนี้ไม่ได้';if(this.d.buildings.filter(function(a){return a.type===type;}).length>=b.cap)return'ครบจำนวนอาคารชนิดนี้แล้ว';if(this.hq()<(b.require||((type==='factory'||type==='tesla')?2:1)))return'ต้องมีศูนย์บัญชาการระดับ '+(b.require||2);if(this.d.buildings.some(function(a){return a.until;}))return'ช่างกำลังทำงาน รอหรือใช้เพชรเร่งเวลา';if(this.d.gold<b.cost||this.d.power<b.power)return'ทรัพยากรไม่พอ';this.d.gold-=b.cost;this.d.power-=b.power;this.d.buildings.push({id:this.d.next++,type:type,x:x,y:y,lv:1,collected:this.now(),constructing:true,started:this.now(),until:this.now()+(b.time||(type==='wall'?3:15))*1000});this.save();return'';};
