Engine.prototype.upgrade=function(id){this.sync();var b=this.d.buildings.find(function(b){return b.id===id;});if(!b||b.until||b.lv>=5)return'อัปเกรดไม่ได้';if(b.type!=='hq'&&b.lv>=this.hq()+1)return'อัปเกรดศูนย์บัญชาการก่อน';if(this.d.buildings.some(function(b){return b.until;}))return'ช่างกำลังอัปเกรดอาคารอื่น';var c=this.upgradeCost(b);if(this.d.gold<c.gold||this.d.power<c.power)return'ทรัพยากรไม่พอ';this.d.gold-=c.gold;this.d.power-=c.power;b.started=this.now();b.until=b.started+c.time*1000;this.save();return'';};
Engine.prototype.train=function(i){this.sync();var u=U[i];if(!u)return'ไม่พบหน่วย';var lock=this.unitLock(i);if(lock)return lock;if(this.housing()+u.space>this.capacity())return'ค่ายทหารเต็ม สร้างหรืออัปเกรดค่าย';if(this.d.power<u.cost)return'พลังงานไม่พอ';this.d.power-=u.cost;this.d.queue.push({kind:i,started:this.now(),until:this.now()+u.time*1000});this.save();return'';};
