Engine.prototype.unitLock=function(i){var u=U[i];if(!u)return'ไม่พบหน่วย';if(!this.level('barracks'))return'รอโรงฝึกทหารสร้างเสร็จ';if(i>0&&i<4&&!this.level('factory'))return'สร้างโรงงานยานเกราะก่อน';if(u.tech&&this.level('tech')<u.tech)return'ต้องมีโนวาแล็บระดับ '+u.tech;if((i===5||i===7)&&!this.level('airbase'))return'สร้างฐานบินสกายพอร์ตก่อน';return'';};
Engine.prototype.speedCost=function(id){var b=this.d.buildings.find(function(a){return a.id===id;});return b&&b.until?Math.max(0,Math.ceil((b.until-this.now())/30000)):0;};
Engine.prototype.speed=function(id,quoted){this.sync();var b=this.d.buildings.find(function(a){return a.id===id;});if(!b||!b.until)return'งานนี้เสร็จแล้ว';var cost=this.speedCost(id);if(cost>quoted)return'ราคาเปลี่ยน กรุณายืนยันใหม่';if(this.d.gems<cost)return'เพชรไม่พอ';this.d.gems-=cost;b.until=this.now();this.sync();return'';};
Engine.prototype.exchange=function(type){if(type!=='gold'&&type!=='power')return'เลือกทรัพยากรไม่ถูกต้อง';if(this.d.gems<10)return'เพชรไม่พอ';this.sync();if(this.d[type]+500>this.resourceCapacity())return'คลังว่างไม่ถึง 500 อัปเกรดคลังก่อน';this.d.gems-=10;this.d[type]+=500;this.save();return'';};
