Engine.prototype.claim=function(){var day=this.day(),c=this.d.checkin;if(day<=c.day)return 0;var streak=day===c.day+1?c.streak%7+1:1,rewards=[10,15,20,25,30,40,60],amount=rewards[streak-1];this.d.checkin={day:day,streak:streak};this.d.gems+=amount;this.save();return amount;};
