Engine.prototype.reward=function(id){if(typeof id!=='string'||id.length<8||this.d.rewardIds.indexOf(id)>=0)return false;this.d.rewardIds.push(id);this.d.rewardIds=this.d.rewardIds.slice(-100);this.d.gems+=5;this.save();return true;};
Engine.prototype.scout=function(n){if(n<1||n>this.d.stage||n>20)return false;var buildings=[],hpFactor=1+(n-1)*.14;function add(type,x,y,sprite,hp){buildings.push({id:buildings.length,type:type,x:x,y:y,sprite:sprite,hp:hp*hpFactor,max:hp*hpFactor,cool:1});}add('hq',6,6,12,950);add('pod',4,5,13,400);add('power',8,6,13,350);add('gun',5,8,14,340);if(n>1)add('gun',8,4,14,340);add('store',7,8,13,300);if(n>3)add('gun',3,6,14,360);if(n>6)add('pod',5,3,13,400);for(var i=0;i<Math.min(7,2+Math.floor(n/3));i++)add('wall',3+i,9,-1,140);if(n%5===0){add('boss',6,3,15,1200);buildings[buildings.length-1].boss=true;}this.raid={stage:n,phase:'scout',time:150,buildings:buildings,guards:[{x:4,y:6,hp:110,max:110,cool:0},{x:7,y:5,hp:110,max:110,cool:0}],troops:[],fx:[],deployed:0,result:null};return true;};
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}
